export function batches(items, width) {
  if (!Number.isInteger(width) || width <= 0) throw new RangeError('width');
  const result = [];
  for (let offset = 0; offset <= items.length; offset += width) {
    result.push(items.slice(offset, offset + width));
  }
  return result;
}
